SELECT
    c.name AS categoryName,
    COALESCE(SUM(t.amount), 0) AS amount,
    ROUND(COALESCE(SUM(t.amount), 0) * 100.0 / NULLIF(total, 0), 2) AS percentage
FROM finance_transaction t
JOIN finance_category c ON t.category_id = c.id
CROSS JOIN (
    SELECT COALESCE(SUM(t2.amount), 0) AS total
    FROM finance_transaction t2
    JOIN finance_category c2 ON t2.category_id = c2.id
    WHERE t2.user_id = #{userId}
      AND c2.type = 1
      AND t2.create_time >= #{startDate}
      AND t2.create_time <= #{endDate}
) sub
WHERE t.user_id = #{userId}
  AND c.type = 1
  AND t.create_time >= #{startDate}
  AND t.create_time <= #{endDate}
GROUP BY c.id, c.name, sub.total
ORDER BY amount DESC

SELECT
    t.id, t.user_id, t.category_id, t.amount, t.tag,
    t.remark, t.create_time, t.update_time,
    c.name AS categoryName, c.type AS categoryType
FROM finance_transaction t
LEFT JOIN finance_category c ON t.category_id = c.id
WHERE t.user_id = #{userId}

    AND t.category_id = #{categoryId}


    AND t.tag = #{tag}


    AND t.create_time >= #{startDate}


    AND t.create_time < #{endDate}

ORDER BY t.create_time DESC

SELECT
    t.id, t.user_id, t.category_id, t.amount, t.tag,
    t.remark, t.create_time, t.update_time,
    c.name AS categoryName, c.type AS categoryType
FROM finance_transaction t
LEFT JOIN finance_category c ON t.category_id = c.id
WHERE t.user_id = #{userId}

    AND t.category_id = #{categoryId}


    AND t.tag = #{tag}


    AND t.create_time >= #{startDate}


    AND t.create_time < #{endDate}

ORDER BY t.create_time ASC
